function selfThreshold(nums: number[]): number {
  const s = [...nums].sort((a, b) => a - b);
  const n = s.length;
  // number of elements >= x
  const countAtLeast = (x: number): number => {
    let lo = 0, hi = n;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (s[mid] >= x) hi = mid;
      else lo = mid + 1;
    }
    return n - lo;
  };
  let lo = 0, hi = n;
  while (lo <= hi) {
    const x = (lo + hi) >> 1;
    const c = countAtLeast(x);
    if (c === x) return x;
    if (c > x) lo = x + 1;
    else hi = x - 1;
  }
  return -1;
}

