function selfThreshold(nums: number[]): number {
  const n = nums.length;
  const buckets = new Array(n + 1).fill(0);
  for (const v of nums) buckets[Math.min(v, n)]++;
  let atLeast = 0;
  for (let x = n; x >= 0; x--) {
    atLeast += buckets[x];
    if (atLeast === x) return x;
  }
  return -1;
}

